# Print document structure
def explore(obj, depth=0, max_depth=5):
    if depth > max_depth:
        return
    if isinstance(obj, dict):
        for k, v in obj.items():
            if isinstance(v, (dict, list)):
                print("  " * depth + f"{k}: ({type(v).__name__})")
                explore(v, depth+1, max_depth)
            elif isinstance(v, str) and len(v) > 100:
                print("  " * depth + f"{k}: str({len(v)} chars)")
            else:
                print("  " * depth + f"{k}: {repr(v)[:50]}")

# Look for tables in the document
def find_tables(obj, path=''):
    results = []
    if isinstance(obj, dict):
        for k, v in obj.items():
            if 'table' in k.lower() or 'thead' in k.lower() or 'tbody' in k.lower():
                results.append((path + '.' + k, v))
            results.extend(find_tables(v, path + '.' + k))
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            results.extend(find_tables(v, path + f'[{i}]'))
    return results

